				userCss: { present: false, ok: null, bytes: 0, errors: [], warnings: [], firstError: null, rewrittenCount: 0, lineCount: 0 },
				userCssText: "",
				userCssEl: null,
				preview: null,
				previewEl: null,
				committedSetTokens: [],
				safeMode: false,
				assetBase: null,
				hooks: null,
				active: false,
				scheme: "light",
				lastApplyAt: null,
				lastReason: null,
				mismatch: [],
				missing: [],
				unverifiable: [],
				fallbackNames: [],
				lastError: null,
				startupFrameGrid: null,
				themeEvents: 0,
				applying: false,
				verifyTimers: [],
				verifyPoll: null,
				verifyPollTicks: 0,
				bodyObserver: null,
				verifyDebounce: null,
				probeTimers: [],
				offTheme: null,
				offStore: null,
				offInject: null,
				listeners: new Set(),
